import "server-only";
import { createClient as createSupabaseClient } from "@supabase/supabase-js";

if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
  throw new Error("SUPABASE_SERVICE_ROLE_KEY is missing from .env.local");
}

let _adminClient: ReturnType<typeof createSupabaseClient> | null = null;

// Service-role client bypasses Row Level Security — server-only, never expose to client.
export function getAdminClient() {
  if (!_adminClient) {
    _adminClient = createSupabaseClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!,
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      },
    );
  }
  return _adminClient;
}

