import "server-only";
import { getAdminClient } from "./admin";

/**
 * IMPORTANT: This module uses the service-role client which bypasses Row Level
 * Security. Never expose these helpers directly to user input — always validate
 * `table` and filter column names against a static whitelist before calling.
 */

export async function getRow<T>(
  table: string,
  id: string | number,
): Promise<T | null> {
  const { data, error } = await getAdminClient()
    .from(table)
    .select("*")
    .eq("id", id)
    .single();
  if (error) {
    if (error.code === "PGRST116") return null;
    throw new Error(error.message);
  }
  return data as T;
}

export async function insertRow<T>(
  table: string,
  data: Record<string, unknown>,
): Promise<T> {
  const { data: result, error } = await getAdminClient()
    .from(table)
    .insert(data)
    .select()
    .single();
  if (error) throw new Error(error.message);
  return result as T;
}

export async function updateRow<T>(
  table: string,
  id: string | number,
  data: Record<string, unknown>,
): Promise<T> {
  const { data: result, error } = await getAdminClient()
    .from(table)
    .update(data)
    .eq("id", id)
    .select()
    .single();
  if (error) throw new Error(error.message);
  return result as T;
}

export async function deleteRow(
  table: string,
  id: string | number,
): Promise<void> {
  const { error } = await getAdminClient()
    .from(table)
    .delete()
    .eq("id", id);
  if (error) throw new Error(error.message);
}

export async function queryRows<T>(
  table: string,
  filters?: Record<string, unknown>,
): Promise<T[]> {
  let query = getAdminClient().from(table).select("*");
  if (filters) {
    for (const [key, value] of Object.entries(filters)) {
      query = query.eq(key, value) as typeof query;
    }
  }
  const { data, error } = await query;
  if (error) throw new Error(error.message);
  return (data ?? []) as T[];
}

