import "server-only";
import { getAdminClient } from "./admin";

/**
 * Rejects storage paths that could escape the intended directory or contain
 * null bytes. Callers passing user-controlled input should still scope paths
 * with a user-id prefix on top of this check.
 */
function assertSafePath(path: string): void {
  if (!path || path.length === 0) {
    throw new Error("path is required.");
  }
  if (path.includes("\0")) {
    throw new Error("path contains a null byte.");
  }
  if (path.startsWith("/")) {
    throw new Error("path must not start with '/'.");
  }
  const segments = path.split("/");
  if (segments.some((s) => s === ".." || s === ".")) {
    throw new Error("path must not contain '.' or '..' segments.");
  }
}

export async function uploadFile(
  bucket: string,
  path: string,
  file: Buffer | Blob,
  options?: { contentType?: string; upsert?: boolean },
): Promise<string> {
  assertSafePath(path);
  // Default to upsert=false — overwriting existing files is opt-in to prevent
  // accidental data replacement when paths collide.
  const { error } = await getAdminClient()
    .storage
    .from(bucket)
    .upload(path, file, {
      contentType: options?.contentType,
      upsert: options?.upsert ?? false,
    });
  if (error) throw new Error(error.message);
  const { data } = getAdminClient().storage.from(bucket).getPublicUrl(path);
  return data.publicUrl;
}

export async function getSignedUrl(
  bucket: string,
  path: string,
  expiresIn = 3600,
): Promise<string> {
  assertSafePath(path);
  const { data, error } = await getAdminClient()
    .storage
    .from(bucket)
    .createSignedUrl(path, expiresIn);
  if (error) throw new Error(error.message);
  return data.signedUrl;
}

export async function deleteFile(bucket: string, path: string): Promise<void> {
  assertSafePath(path);
  const { error } = await getAdminClient()
    .storage
    .from(bucket)
    .remove([path]);
  if (error) throw new Error(error.message);
}

export async function createBucket(
  name: string,
  isPublic = false,
): Promise<void> {
  const { error } = await getAdminClient()
    .storage
    .createBucket(name, { public: isPublic });
  // Ignore "already exists" — makes this safe to call idempotently.
  if (error && !error.message.toLowerCase().includes("already exists")) {
    throw new Error(error.message);
  }
}

