"use client";

import { createClient } from "./client";

/**
 * SECURITY: These helpers run in the browser using the anon key. The server
 * cannot enforce who subscribes to which table here — Postgres Row Level
 * Security policies are the ONLY thing protecting your data. Before using
 * realtime in production:
 *   1. Enable RLS on every table you expose: `ALTER TABLE foo ENABLE ROW LEVEL SECURITY;`
 *   2. Write SELECT policies scoped to `auth.uid()`.
 *   3. Enable Realtime publication only for the tables that should be exposed.
 * If you accept user-controlled `table` or `channel` names, whitelist them
 * against a static set in your caller — don't pass raw user input.
 */

// PostgreSQL identifier syntax: letters, digits, underscores; must start with
// a letter or underscore. This validation prevents channel-name injection like
// `table; DROP TABLE` even though Supabase parameterizes the value internally.
const VALID_IDENTIFIER = /^[A-Za-z_][A-Za-z0-9_]*$/;

function assertValidIdentifier(name: string, label: string): void {
  if (!VALID_IDENTIFIER.test(name)) {
    throw new Error(
      `Invalid ${label} "${name}": must match /^[A-Za-z_][A-Za-z0-9_]*$/.`,
    );
  }
}

export function subscribeToTable<T extends Record<string, unknown>>(
  table: string,
  callback: (record: T) => void,
  event: "INSERT" | "UPDATE" | "DELETE" | "*" = "*",
): () => void {
  assertValidIdentifier(table, "table name");
  const supabase = createClient();
  const channel = supabase
    .channel(`table:${table}`)
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    .on("postgres_changes" as any, { event, schema: "public", table }, (payload: { new: T }) => {
      callback(payload.new);
    })
    .subscribe();

  return () => {
    supabase.removeChannel(channel);
  };
}

export function subscribeToChannel(
  channel: string,
  event: string,
  callback: (payload: unknown) => void,
): () => void {
  const supabase = createClient();
  const ch = supabase
    .channel(channel)
    .on("broadcast", { event }, ({ payload }: { payload: unknown }) => {
      callback(payload);
    })
    .subscribe();

  return () => {
    supabase.removeChannel(ch);
  };
}
